using NUnit.Framework;

[TestFixture]
public class IsPalindromeWordTests
{
    [TestCase("level", true)]
    [TestCase("hello", false)]
    public void Checks_Palindrome(string word, bool expected)
    {
        Assert.That(IsPalindromeWord(word), Is.EqualTo(expected));
    }

    private bool IsPalindromeWord(string word)
    {
        int left = 0;
        int right = word.Length - 1;

        while (left < right)
        {
            if (word[left] != word[right])
                return false;

            left++;
            right--;
        }

        return true;
    }
}
